const PREGUNTAS = [
  { id: "nube1", tp: "nube", q: "¿Qué describe mejor la computación en la nube?", o: ["Entregar servicios de cómputo (servidores, storage, redes, bases de datos, software) por internet, pagando por lo que usas", "Comprar hardware propio e instalarlo en tu datacenter", "Instalar software solo en las computadoras de la oficina", "Una red privada que conecta sucursales"], a: [0], e: "La nube es rentar capacidad de cómputo por internet en vez de comprarla. Tú no ves los servidores; los usas como servicio.", c: "\"por internet\" + \"pago por uso\" = nube." },
  { id: "nube2", tp: "nube", x: 1, q: "¿Qué dos características describen una nube pública?", o: ["El hardware es propiedad de un proveedor externo", "Se ofrece por internet a cualquier persona u organización", "El hardware vive en el datacenter de la propia organización", "La usa exclusivamente una sola organización"], a: [0, 1], e: "Pública = el edificio de departamentos: el dueño es el proveedor (Microsoft) y cualquiera puede rentar. Hardware en tu propio datacenter o de uso exclusivo es nube privada.", c: "\"propiedad de un tercero\" o \"disponible para cualquiera\" = pública." },
  { id: "nube3", tp: "nube", q: "Por regulación, una aseguradora necesita que su infraestructura sea de uso exclusivo y la administre su propio equipo de TI. ¿Qué modelo usa?", o: ["Nube privada", "Nube pública", "Nube híbrida", "SaaS"], a: [0], e: "Privada = casa propia: solo tú la usas y tú la mantienes. Puede estar en tu datacenter o hospedada por un tercero, pero es exclusiva.", c: "\"uso exclusivo\" o \"control total del hardware\" = privada." },
  { id: "nube4", tp: "nube", q: "Un banco mantiene su sistema central en su propio datacenter y publica su app móvil en Azure, con ambos conectados. ¿Qué modelo es?", o: ["Nube híbrida", "Nube pública", "Nube privada", "Multinube"], a: [0], e: "Híbrida = parte en tu casa (privada) y parte rentada (pública), conectadas y trabajando juntas.", c: "\"on-premises + Azure conectados\" = híbrida." },
  { id: "nube5", tp: "nube", q: "¿Qué escenario justifica mejor una nube híbrida?", o: ["Mantener datos sensibles en tu datacenter por regulación y usar Azure para absorber picos de demanda", "Una startup sin servidores propios que lanza su primera app", "Una empresa que solo usa Microsoft 365", "Un laboratorio que quiere hardware exclusivo sin internet"], a: [0], e: "El caso clásico de híbrida: lo regulado se queda en casa y la nube pone la capacidad extra cuando hace falta.", c: "\"mantener on-prem\" + \"aprovechar la nube\" = híbrida." },

  { id: "resp1", tp: "resp", q: "Despliegas una máquina virtual en Azure (IaaS). ¿Quién es responsable de instalar los parches del sistema operativo?", o: ["Tú, el cliente", "Microsoft", "Ambos por partes iguales", "Nadie, las VMs no requieren parches"], a: [0], e: "IaaS = te rentan la cocina: Microsoft pone el edificio, la luz y el hardware; tú cocinas y limpias. El sistema operativo de la VM es tuyo.", c: "\"VM\" o \"IaaS\" + \"parchar el SO\" = el cliente." },
  { id: "resp2", tp: "resp", q: "En un servicio PaaS como Azure App Service, ¿quién parcha el sistema operativo?", o: ["Microsoft", "El cliente", "El desarrollador de la app", "Depende de la región"], a: [0], e: "PaaS = pizza a domicilio: la cocina y el horno ya no son tu problema. El sistema operativo es la línea: en IaaS es tuyo, en PaaS y SaaS es de Microsoft.", c: "PaaS o SaaS + \"sistema operativo\" = Microsoft." },
  { id: "resp3", tp: "resp", x: 1, q: "¿Qué responsabilidad es SIEMPRE del cliente, sin importar si usa IaaS, PaaS o SaaS?", o: ["La información y los datos", "La red física", "Los hosts físicos", "El sistema operativo"], a: [0], e: "Tus datos, tus dispositivos, tus cuentas y quién tiene acceso son siempre tuyos. Ni en SaaS Microsoft decide qué datos subes ni a quién le das acceso.", c: "\"datos\", \"identidades\", \"cuentas\" o \"dispositivos\" = siempre el cliente." },
  { id: "resp4", tp: "resp", q: "¿Qué es SIEMPRE responsabilidad de Microsoft en la nube pública?", o: ["El datacenter físico, la red física y los hosts", "Las cuentas de usuario", "La clasificación de los datos", "Los dispositivos de los empleados"], a: [0], e: "Lo físico nunca es tuyo en la nube: edificio, cables, servidores. Eso es lo que estás rentando.", c: "\"físico\" (datacenter, red física, hosts) = Microsoft siempre." },
  { id: "resp5", tp: "resp", x: 1, q: "En PaaS, ¿qué dos responsabilidades le tocan al proveedor?", o: ["El sistema operativo", "La red física", "La información y los datos", "Los dispositivos móviles y PCs"], a: [0, 1], e: "En PaaS Microsoft cubre lo físico y además el sistema operativo. Los datos y los dispositivos siguen siendo del cliente.", c: "Datos y dispositivos nunca los pierdes de tu lado." },

  { id: "precio1", tp: "precio", q: "Tu empresa compra 20 servidores y construye un cuarto de servidores. ¿Qué tipo de gasto es?", o: ["CapEx (gasto de capital)", "OpEx (gasto operativo)", "Modelo basado en consumo", "Gasto serverless"], a: [0], e: "CapEx = comprar un coche: pagas mucho por adelantado por algo que es tuyo y se deprecia. OpEx = tomar Uber: pagas cada viaje cuando lo usas.", c: "\"comprar\", \"por adelantado\", \"infraestructura propia\" = CapEx." },
  { id: "precio2", tp: "precio", q: "Una empresa deja de comprar servidores y empieza a pagar una factura mensual de Azure según lo que usa. ¿Qué cambio es?", o: ["De CapEx a OpEx", "De OpEx a CapEx", "De IaaS a SaaS", "De nube pública a privada"], a: [0], e: "Pasas de comprar el coche (CapEx) a pagar Uber por viaje (OpEx). La nube es, por naturaleza, OpEx.", c: "\"pago mensual por uso\" = OpEx." },
  { id: "precio3", tp: "precio", q: "¿Qué significa el modelo basado en consumo?", o: ["Pagas solo por los recursos que usas, sin costo inicial", "Pagas por adelantado una capacidad fija", "Compras licencias perpetuas", "Pagas un único monto al firmar el contrato"], a: [0], e: "Como el recibo de la luz: si apagas, no pagas. Sin inversión inicial y puedes dejar de pagar cuando dejas de usar.", c: "\"pagar solo por lo que usas\" = consumo." },
  { id: "precio4", tp: "precio", q: "Tienes una VM que correrá sin parar los próximos 3 años y quieres el mayor descuento. ¿Qué opción de precio conviene?", o: ["Reservations (reservas de 1 o 3 años)", "Pay-as-you-go", "Spot VMs", "Free account"], a: [0], e: "Reserva = pagar el gimnasio por año: te comprometes y te sale mucho más barato que pagar cada visita. Pay-as-you-go es flexible pero más caro por hora.", c: "\"carga estable\" + \"compromiso de 1 o 3 años\" = reservations." },
  { id: "precio5", tp: "precio", q: "Tienes procesamiento por lotes que puede interrumpirse sin problema y quieres el precio más bajo posible. ¿Qué usas?", o: ["Spot VMs", "Reservations", "Dedicated Hosts", "Availability sets"], a: [0], e: "Spot = asientos de última hora: capacidad sobrante de Azure muy barata, pero Azure te puede sacar cuando la necesita.", c: "\"puede interrumpirse\" + \"menor costo\" = Spot." },
  { id: "precio6", tp: "precio", q: "¿Qué describe mejor serverless?", o: ["No administras servidores: el proveedor escala por ti y pagas por ejecución", "No existen servidores físicos en ningún lado", "Usas VMs muy pequeñas", "Solo funciona en tu datacenter"], a: [0], e: "Los servidores sí existen, pero no los ves ni los administras. Solo escribes el código y Azure lo corre cuando hace falta.", c: "\"sin administrar infraestructura\" + \"pago por ejecución\" = serverless." },
  { id: "precio7", tp: "precio", q: "Quieres ejecutar código cada vez que llega un archivo a un contenedor de storage y pagar solo mientras corre. ¿Qué servicio usas?", o: ["Azure Functions", "Azure Virtual Machines", "Azure Virtual Desktop", "VM Scale Sets"], a: [0], e: "Functions = timbre: no hay nadie parado en la puerta todo el día; cuando suena (el evento), alguien sale a atender.", c: "\"se ejecuta en respuesta a un evento\" = Functions." },

  { id: "benef1", tp: "benef", x: 1, q: "La empresa necesita implementar y configurar recursos rápidamente conforme cambian sus requisitos. ¿Qué beneficio es?", o: ["Agilidad", "Elasticidad", "Alta disponibilidad", "Previsibilidad"], a: [0], e: "Agilidad = rapidez para lanzar cosas NUEVAS (minutos en vez de semanas comprando hardware). Elasticidad = que lo que ya existe crezca y se encoja solo.", c: "\"implementar rápidamente\" = agilidad." },
  { id: "benef2", tp: "benef", q: "En el Buen Fin las VMs de una tienda se agregan solas y al terminar se quitan. ¿Qué beneficio describe?", o: ["Elasticidad", "Agilidad", "Previsibilidad", "Gobernanza"], a: [0], e: "Elasticidad = el piloto automático del escalado: responde solo a la demanda, hacia arriba y hacia abajo. En el material nuevo de Microsoft también aparece como escalabilidad automática.", c: "\"automáticamente según la demanda\" = elasticidad." },
  { id: "benef3", tp: "benef", q: "Le agregas 16 GB de RAM y más CPU a una VM que ya existe. ¿Qué tipo de escalado es?", o: ["Vertical (scale up)", "Horizontal (scale out)", "Elasticidad regional", "Redundancia"], a: [0], e: "Vertical = cambiar tu coche por uno más potente. Horizontal = comprar más coches.", c: "\"más RAM o CPU a la misma máquina\" = vertical." },
  { id: "benef4", tp: "benef", q: "Agregas 4 instancias más de tu app detrás de un balanceador. ¿Qué tipo de escalado es?", o: ["Horizontal (scale out)", "Vertical (scale up)", "Previsibilidad", "Agilidad"], a: [0], e: "Horizontal = más máquinas trabajando en paralelo. Es el que se automatiza con VM Scale Sets.", c: "\"más instancias\" = horizontal." },
  { id: "benef5", tp: "benef", q: "¿Qué beneficio garantiza que un servicio siga disponible aunque falle un componente, y suele pactarse en un SLA?", o: ["Alta disponibilidad", "Agilidad", "Previsibilidad de costos", "Capacidad de administración"], a: [0], e: "Alta disponibilidad = no se cae. Se mide en porcentaje de tiempo arriba (99.9%, 99.99%) y ese compromiso queda en el SLA.", c: "\"tiempo activo\", \"SLA\", \"sin interrupciones\" = alta disponibilidad." },
  { id: "benef6", tp: "benef", q: "Una app está distribuida en varias regiones para recuperarse de fallos y seguir funcionando. ¿Qué beneficio se destaca?", o: ["Confiabilidad (reliability)", "Previsibilidad", "Agilidad", "Gobernanza"], a: [0], e: "Confiabilidad = capacidad de recuperarse de un golpe. La red global de Azure permite diseñar para que una falla en un lugar no tumbe todo.", c: "\"recuperarse de fallas\" = confiabilidad." },
  { id: "benef7", tp: "benef", q: "Usas herramientas para saber de antemano cuánto costará tu solución y cómo rendirá. ¿Qué beneficio es?", o: ["Previsibilidad", "Elasticidad", "Seguridad", "Agilidad"], a: [0], e: "Previsibilidad tiene dos caras: de costo (pricing calculator, reservas) y de rendimiento (autoscaling, balanceo).", c: "\"pronosticar costos\" o \"rendimiento predecible\" = previsibilidad." },
  { id: "benef8", tp: "benef", q: "Usas plantillas y políticas para que todos los recursos cumplan estándares corporativos y regulatorios. ¿Qué beneficio es?", o: ["Gobernanza", "Elasticidad", "Agilidad", "Alta disponibilidad"], a: [0], e: "Gobernanza = reglas del condominio: todos construyen, pero bajo el mismo reglamento. En Azure se aplica con Azure Policy y plantillas.", c: "\"cumplir estándares\" o \"cumplimiento\" = gobernanza." },
  { id: "benef9", tp: "benef", q: "Configuras escalado automático y alertas, y administras todo desde el portal, la CLI o APIs. ¿Qué beneficio describe?", o: ["Capacidad de administración (manageability)", "Previsibilidad", "Confiabilidad", "Consumo"], a: [0], e: "Manageability tiene dos partes: administración DE la nube (autoescalado, alertas, monitoreo) y administración EN la nube (portal, CLI, APIs, PowerShell).", c: "\"administrar desde portal/CLI/API\" o \"alertas automáticas\" = manageability." },

  { id: "tipos1", tp: "tipos", q: "Una empresa quiere migrar tal cual sus servidores a la nube (lift-and-shift) y conservar el máximo control del sistema operativo. ¿Qué tipo de servicio usa?", o: ["IaaS", "PaaS", "SaaS", "Serverless"], a: [0], e: "IaaS = rentar la cocina vacía: la cocinas a tu gusto. Es el que más control da y el más parecido a tener tus propios servidores.", c: "\"lift-and-shift\" o \"control total\" = IaaS." },
  { id: "tipos2", tp: "tipos", x: 1, q: "Un equipo quiere enfocarse en desarrollar su app sin administrar servidores ni sistemas operativos. ¿Qué tipo de servicio le conviene?", o: ["PaaS", "SaaS", "IaaS", "On-premises"], a: [0], e: "PaaS = pizza lista a domicilio: tú solo pones tu negocio (el código). SaaS no aplica porque ahí ni siquiera escribes la app; solo la usas.", c: "\"escribir código sin administrar infraestructura\" = PaaS." },
  { id: "tipos3", tp: "tipos", x: 1, q: "¿Qué tipo de servicio es Azure SQL Database?", o: ["PaaS", "SaaS", "IaaS", "Serverless puro"], a: [0], e: "Es un motor de base de datos administrado: Microsoft parcha y respalda, tú diseñas tus tablas y datos. Las bases administradas (Azure SQL Database, Cosmos DB) son PaaS.", c: "\"base de datos administrada\" = PaaS. \"SQL Server dentro de una VM\" = IaaS." },
  { id: "tipos4", tp: "tipos", q: "Tu empresa usa Microsoft 365 (Outlook, Teams) sin instalar ni mantener nada. ¿Qué tipo de servicio es?", o: ["SaaS", "PaaS", "IaaS", "Nube privada"], a: [0], e: "SaaS = ir al restaurante: solo comes. Usas el software terminado y te cobran una suscripción.", c: "\"usar software terminado\" o \"suscripción por usuario\" = SaaS." },
  { id: "tipos5", tp: "tipos", q: "¿Qué tipo de servicio le da MÁS control y MÁS responsabilidad al cliente?", o: ["IaaS", "PaaS", "SaaS", "Todos por igual"], a: [0], e: "El control va de más a menos: IaaS > PaaS > SaaS. La responsabilidad del cliente baja en el mismo orden.", c: "\"máximo control\" = IaaS. \"mínimo esfuerzo de administración\" = SaaS." },
  { id: "tipos6", tp: "tipos", q: "Analistas crean reportes con Power BI desde el navegador sin programar ni instalar servidores. ¿Qué tipo de servicio es Power BI?", o: ["SaaS", "PaaS", "IaaS", "Serverless"], a: [0], e: "Es una aplicación terminada que consumes con suscripción, como Microsoft 365.", c: "\"sin código\" + \"aplicación lista\" = SaaS." },

  { id: "geo1", tp: "geo", q: "¿Qué es una región de Azure?", o: ["Un área geográfica con uno o más datacenters conectados por una red de baja latencia", "Un solo datacenter", "Un grupo de suscripciones", "Un rack dentro de un datacenter"], a: [0], e: "Región = una ciudad con varios edificios de Azure (ej. Mexico Central, East US). Eliges región para estar cerca de tus usuarios o cumplir leyes de residencia de datos.", c: "\"ubicación geográfica\" donde despliegas = región." },
  { id: "geo2", tp: "geo", q: "Quieres que tu app siga funcionando si falla un datacenter completo, pero dentro de la misma región. ¿Qué usas?", o: ["Availability zones", "Region pairs", "Availability sets", "Resource groups"], a: [0], e: "Availability zones = edificios distintos en la misma ciudad, cada uno con su propia luz, enfriamiento y red. Si se cae un edificio, los otros siguen.", c: "\"falla de un datacenter\" + \"misma región\" = availability zones." },
  { id: "geo3", tp: "geo", q: "Quieres protegerte de un desastre que deja fuera de servicio una región completa (un sismo grande). ¿Qué aprovechas?", o: ["Region pairs (otra región)", "Availability zones", "Availability sets", "Un segundo resource group"], a: [0], e: "Si se cae la ciudad entera, los edificios de esa ciudad no te salvan. Necesitas el gemelo en otra ciudad: la región par.", c: "\"falla de toda la región\" = otra región / region pair." },
  { id: "geo4", tp: "geo", q: "¿Qué es cierto de una availability zone?", o: ["Está formada por uno o más datacenters con energía, enfriamiento y red independientes", "Es una región completa", "Es un rack de servidores", "Existe en todas las regiones sin excepción"], a: [0], e: "Cada zona es físicamente independiente. Las regiones que las soportan tienen al menos 3 zonas, pero no todas las regiones tienen zonas.", c: "\"independiente\" + \"dentro de la región\" = availability zone." },
  { id: "geo5", tp: "geo", q: "¿Qué ventaja tienen las regiones en par (region pairs) durante un mantenimiento planeado de Azure?", o: ["Las actualizaciones se aplican a una región del par a la vez", "Nunca reciben mantenimiento", "Se actualizan ambas al mismo tiempo para terminar rápido", "El mantenimiento solo ocurre en fin de semana"], a: [0], e: "Microsoft escalona las actualizaciones: primero una región del par y luego la otra. Además, si hay una caída amplia, se prioriza recuperar una región de cada par.", c: "\"actualizaciones escalonadas\" o \"prioridad de recuperación\" = region pairs." },
  { id: "geo6", tp: "geo", q: "El gobierno de EE. UU. necesita una instancia de Azure aislada físicamente y operada por personal verificado. ¿Qué tipo de región es?", o: ["Sovereign region (región soberana)", "Region pair", "Availability zone", "Región pública estándar"], a: [0], e: "Las regiones soberanas están separadas del Azure público por razones legales: Azure Government (EE. UU.) y Azure en China, operado por 21Vianet.", c: "\"gobierno\" o \"aislada por cumplimiento legal\" = sovereign region." },
  { id: "geo7", tp: "geo", q: "Quieres que tus VMs no se caigan juntas por una falla de rack o un reinicio por actualización DENTRO de un mismo datacenter. ¿Qué usas?", o: ["Availability sets", "Availability zones", "Region pairs", "VM Scale Sets con otra región"], a: [0], e: "Availability set = repartir tus VMs en distintos racks (fault domains) y grupos de reinicio (update domains) del MISMO datacenter. Las zonas protegen de un edificio completo.", c: "\"rack\", \"fault domain\", \"update domain\" = availability set." },

  { id: "jer1", tp: "jer", x: 1, q: "¿Qué dos cosas se crean DENTRO de una suscripción?", o: ["Resource groups", "Recursos (por ejemplo, VMs)", "Management groups", "Cuentas de usuario de Microsoft Entra ID"], a: [0, 1], e: "Los management groups están ARRIBA de las suscripciones. Las cuentas de Entra ID viven en el tenant, no en una suscripción.", c: "Jerarquía: Management group → Suscripción → Resource group → Recurso." },
  { id: "jer2", tp: "jer", x: 1, q: "Un área de la empresa necesita recibir su propia factura separada de Azure. ¿Qué creas?", o: ["Una suscripción", "Un management group", "Un resource group", "Una etiqueta (tag)"], a: [0], e: "La suscripción es la unidad de facturación y un límite de acceso. Cada una genera su propia factura.", c: "\"facturación separada\" = suscripción." },
  { id: "jer3", tp: "jer", q: "Quieres aplicar la misma Azure Policy y los mismos permisos a 12 suscripciones de una sola vez. ¿Qué usas?", o: ["Un management group", "Un resource group", "Un availability set", "Una región"], a: [0], e: "Management group = carpeta de suscripciones. Lo que asignas ahí lo heredan todas las suscripciones de adentro.", c: "\"varias suscripciones\" = management group." },
  { id: "jer4", tp: "jer", q: "¿En cuántos resource groups puede estar un recurso al mismo tiempo?", o: ["Exactamente en uno", "En hasta tres", "En todos los de su suscripción", "En ninguno si es global"], a: [0], e: "Un recurso vive en un solo resource group (se puede mover, pero nunca está en dos). Si quieres agrupar por otro criterio, usas tags.", c: "\"un recurso, un resource group\"." },
  { id: "jer5", tp: "jer", q: "¿Qué pasa si eliminas un resource group?", o: ["Se eliminan todos los recursos que contiene", "Los recursos pasan a otro grupo", "Solo se borra el nombre del grupo", "Se elimina la suscripción"], a: [0], e: "Borrar el cajón tira todo lo que tiene adentro. Por eso conviene agrupar por ciclo de vida: lo que nace y muere junto va en el mismo resource group.", c: "\"eliminar el grupo\" = se eliminan sus recursos." },
  { id: "jer6", tp: "jer", q: "¿Puede un resource group contener recursos de distintas regiones?", o: ["Sí", "No, todos deben estar en la región del grupo", "Solo si son VMs", "Solo con un management group"], a: [0], e: "El resource group tiene una región para guardar sus metadatos, pero sus recursos pueden estar en cualquier región.", c: "El resource group es un contenedor lógico, no geográfico." },
  { id: "jer7", tp: "jer", q: "Asignas el rol Reader a una persona en un resource group. ¿A qué tiene acceso?", o: ["A leer todos los recursos dentro de ese resource group", "Solo al resource group vacío", "A toda la suscripción", "A todos los management groups"], a: [0], e: "Los permisos y las políticas se heredan hacia abajo: lo asignado en un nivel aplica a todo lo que está debajo.", c: "Asignar arriba = heredar abajo." },
  { id: "jer8", tp: "jer", q: "¿Se pueden anidar resource groups (un grupo dentro de otro)?", o: ["No", "Sí, hasta 6 niveles", "Sí, sin límite", "Solo en suscripciones Enterprise"], a: [0], e: "Los resource groups no se anidan. Lo que sí se anida son los management groups (hasta 6 niveles bajo la raíz).", c: "Anidar = management groups, nunca resource groups." },

  { id: "comp1", tp: "comp", q: "Quieres empaquetar tu app con sus dependencias, que arranque en segundos y sea más ligera que una VM porque no carga un sistema operativo completo. ¿Qué usas?", o: ["Contenedores", "Máquinas virtuales", "Azure Virtual Desktop", "Availability sets"], a: [0], e: "VM = casa completa con cimientos propios (su propio SO). Contenedor = departamento: comparte el edificio (el kernel) y solo trae sus muebles.", c: "\"ligero\", \"portable\", \"arranca en segundos\" = contenedores." },
  { id: "comp2", tp: "comp", q: "Necesitas un grupo de VMs idénticas que aumente o reduzca instancias automáticamente según la carga. ¿Qué usas?", o: ["Virtual Machine Scale Sets", "Availability sets", "Azure Virtual Desktop", "Azure Container Instances"], a: [0], e: "Scale Sets = contratar y despedir meseros idénticos según la gente que llega. Todas las VMs usan la misma configuración.", c: "\"VMs idénticas\" + \"escalado automático\" = Scale Sets." },
  { id: "comp3", tp: "comp", q: "Los empleados necesitan un escritorio de Windows en la nube al que puedan entrar desde cualquier dispositivo. ¿Qué servicio es?", o: ["Azure Virtual Desktop", "Azure Virtual Machines Scale Sets", "Azure App Service", "Azure Functions"], a: [0], e: "Azure Virtual Desktop entrega escritorios y apps de Windows desde la nube, con los datos fuera de la laptop del empleado.", c: "\"escritorio virtual\" o \"acceso desde cualquier dispositivo\" = Azure Virtual Desktop." },
  { id: "comp4", tp: "comp", q: "Al crear una VM, ¿qué dos recursos se necesitan además de la VM?", o: ["Un disco (managed disk)", "Una interfaz de red (NIC) en una virtual network", "Un App Service plan", "Una cola de Storage"], a: [0, 1], e: "Una VM necesita disco para el sistema operativo y red para comunicarse (NIC en una VNet). También suele llevar IP pública y un grupo de seguridad de red, pero son opcionales.", c: "Recursos de una VM: tamaño, discos, VNet/NIC, IP pública opcional." },
  { id: "comp5", tp: "comp", q: "Quieres hospedar una app web en .NET o Node.js sin administrar el sistema operativo, con escalado y despliegue continuo integrados. ¿Qué eliges?", o: ["Azure App Service", "Una VM", "Azure Virtual Desktop", "Azure Data Box"], a: [0], e: "App Service es PaaS para web apps y APIs: subes el código y Azure se encarga del servidor.", c: "\"web app\" + \"sin administrar servidores\" = App Service." },
  { id: "comp6", tp: "comp", q: "Una app antigua requiere instalar software especial en el servidor y configurar el SO a mano. ¿Qué opción de hosting conviene?", o: ["Máquinas virtuales", "App Service", "Azure Functions", "Microsoft 365"], a: [0], e: "Cuando necesitas control del sistema operativo, la respuesta es una VM (IaaS).", c: "\"control del SO\" o \"software personalizado en el servidor\" = VM." },
  { id: "comp7", tp: "comp", q: "Quieres correr un solo contenedor rápido sin administrar VMs ni un orquestador. ¿Qué usas?", o: ["Azure Container Instances", "Azure Kubernetes Service", "VM Scale Sets", "Azure Virtual Desktop"], a: [0], e: "Container Instances es la forma más simple de correr un contenedor. Si tienes muchos contenedores que coordinar, entonces Kubernetes (AKS).", c: "\"un contenedor, lo más simple\" = ACI. \"orquestar muchos\" = AKS." },

  { id: "red1", tp: "red", q: "¿Para qué sirve una Azure Virtual Network (VNet)?", o: ["Para que tus recursos de Azure se comuniquen de forma privada entre sí, con internet y con tu red local", "Para almacenar archivos", "Para facturar por departamento", "Para asignar roles"], a: [0], e: "La VNet es tu red privada dentro de Azure: aísla y conecta tus recursos. Las subnets la dividen en segmentos.", c: "\"comunicación privada entre recursos\" = VNet." },
  { id: "red2", tp: "red", q: "Quieres conectar dos VNets para que sus recursos se hablen con IPs privadas por la red de Microsoft. ¿Qué usas?", o: ["VNet peering", "VPN Gateway", "Azure DNS", "Un public endpoint"], a: [0], e: "Peering = un pasillo privado entre dos redes de Azure, incluso de regiones distintas. El tráfico no pasa por internet público.", c: "\"conectar dos VNets\" = peering." },
  { id: "red3", tp: "red", q: "La oficina de CDMX necesita conectarse a Azure con tráfico cifrado que viaja por internet público. ¿Qué usa?", o: ["VPN Gateway", "ExpressRoute", "VNet peering", "Azure DNS"], a: [0], e: "VPN = túnel cifrado por la carretera pública (internet). Barato y rápido de configurar.", c: "\"cifrado por internet\" = VPN Gateway." },
  { id: "red4", tp: "red", q: "Un banco necesita una conexión privada y dedicada entre su datacenter y Azure que NO pase por internet público. ¿Qué usa?", o: ["ExpressRoute", "VPN Gateway", "VNet peering", "Un public endpoint"], a: [0], e: "ExpressRoute = autopista privada de cuota: línea dedicada a través de un proveedor de conectividad. Más confiable y predecible, y más cara.", c: "\"no pasa por internet\" o \"conexión dedicada\" = ExpressRoute." },
  { id: "red5", tp: "red", q: "Quieres hospedar los registros DNS de tu dominio y resolverlos con la infraestructura de Azure. ¿Qué usas?", o: ["Azure DNS", "Azure Virtual Network", "ExpressRoute", "Microsoft Entra ID"], a: [0], e: "Azure DNS hospeda tus zonas DNS. Ojo: no sirve para comprar el dominio, solo para administrar sus registros.", c: "\"registros DNS\" o \"resolución de nombres\" = Azure DNS." },
  { id: "red6", tp: "red", x: 1, q: "Una VM en tu VNet debe acceder a Azure SQL Database de forma privada, sin exponer la base de datos a internet. ¿Qué usas?", o: ["Un private endpoint", "ExpressRoute", "VPN Gateway", "Azure DNS"], a: [0], e: "Private endpoint = darle al servicio una IP privada dentro de tu VNet, como si viviera en tu red. ExpressRoute y VPN son para conectar tu oficina con Azure, no un servicio de Azure con tu VNet.", c: "\"servicio de Azure accesible solo desde mi VNet\" = private endpoint." },
  { id: "red7", tp: "red", q: "¿Qué es un public endpoint?", o: ["Una dirección accesible desde internet", "Una IP privada dentro de tu VNet", "Una conexión dedicada a tu datacenter", "Un túnel VPN"], a: [0], e: "Public endpoint = puerta a la calle. Private endpoint = puerta interior que solo abre desde tu red.", c: "\"accesible por internet\" = public endpoint." },

  { id: "stor1", tp: "stor", q: "Necesitas guardar millones de imágenes, videos y respaldos no estructurados, accesibles por HTTP/HTTPS. ¿Qué servicio usas?", o: ["Blob Storage", "Azure Files", "Queue Storage", "Azure Disks"], a: [0], e: "Blob = bodega gigante de objetos: cualquier archivo, sin estructura, por URL.", c: "\"no estructurados\", \"imágenes/video\", \"por URL\" = Blob." },
  { id: "stor2", tp: "stor", x: 1, q: "¿Qué dos protocolos usa Azure Files para montar recursos compartidos?", o: ["SMB", "NFS", "HTTP", "FTP"], a: [0, 1], e: "Azure Files = carpeta compartida de red en la nube, que se monta como una unidad de red con SMB o NFS. Blob es el que se consume por HTTP/REST.", c: "\"file share\" o \"montar una unidad\" = Azure Files (SMB/NFS)." },
  { id: "stor3", tp: "stor", q: "Dos partes de tu app necesitan pasarse mensajes de forma asíncrona. ¿Qué servicio de storage usas?", o: ["Queue Storage", "Table Storage", "Blob Storage", "Azure Disks"], a: [0], e: "Queue = fila de tortillería: los mensajes esperan su turno hasta que alguien los procesa.", c: "\"mensajes entre componentes\" = Queue." },
  { id: "stor4", tp: "stor", q: "¿Qué servicio ofrece discos administrados para las VMs?", o: ["Azure Disks", "Azure Files", "Blob Storage (archive)", "Table Storage"], a: [0], e: "Azure Disks son los discos duros virtuales de las VMs, en SSD o HDD.", c: "\"disco de VM\" = Azure Disks." },
  { id: "stor5", tp: "stor", x: 1, q: "Respaldos que casi nunca se consultan, al menor costo de almacenamiento, aunque leerlos tarde horas. ¿Qué tier usas?", o: ["Archive", "Cool", "Cold", "Hot"], a: [0], e: "Archive = la bodega fuera de la ciudad: guardar ahí es baratísimo, pero traer algo tarda horas (hay que rehidratarlo) y cuesta más. Está fuera de línea.", c: "\"rara vez\" + \"puede tardar horas\" = Archive." },
  { id: "stor6", tp: "stor", q: "Datos a los que accedes poco, que se guardan al menos 30 días y deben estar disponibles de inmediato. ¿Qué tier conviene?", o: ["Cool", "Hot", "Archive", "Premium"], a: [0], e: "Hot = uso frecuente. Cool = poco frecuente (30 días o más). Cold = raro (90 días o más). Archive = casi nunca (180 días o más, fuera de línea). Los tres primeros están en línea.", c: "\"poco frecuente\" + \"disponible inmediato\" = Cool (o Cold si es muy raro)." },
  { id: "stor7", tp: "stor", q: "¿Qué tier tiene el MAYOR costo de almacenamiento pero el MENOR costo de acceso?", o: ["Hot", "Cool", "Cold", "Archive"], a: [0], e: "Es un balance: entre más frío, más barato guardar y más caro leer.", c: "Caliente = caro guardar, barato leer. Frío = al revés." },
  { id: "stor8", tp: "stor", q: "Quieres la opción de redundancia más barata: 3 copias dentro de un solo datacenter. ¿Cuál es?", o: ["LRS", "ZRS", "GRS", "GZRS"], a: [0], e: "LRS (locally redundant) = 3 copias en el mismo edificio. Te protege de que falle un disco, no de que falle el edificio.", c: "\"más barata\" o \"un datacenter\" = LRS." },
  { id: "stor9", tp: "stor", q: "Quieres que tus datos sobrevivan a la caída de un datacenter, con copias en 3 availability zones de la misma región. ¿Qué redundancia usas?", o: ["ZRS", "LRS", "GRS", "RA-GRS"], a: [0], e: "ZRS (zone-redundant) = 3 copias en 3 edificios de la misma ciudad, sincronizadas.", c: "\"availability zones\" + \"misma región\" = ZRS." },
  { id: "stor10", tp: "stor", q: "Necesitas proteger tus datos contra la pérdida de una región completa. ¿Qué redundancia eliges?", o: ["GRS", "LRS", "ZRS", "Premium SSD"], a: [0], e: "GRS (geo-redundant) = 3 copias en tu región + 3 copias en la región par, a cientos de kilómetros. La copia a la otra región es asíncrona.", c: "\"desastre regional\" = GRS o GZRS." },
  { id: "stor11", tp: "stor", q: "Además de tener copia en otra región, necesitas poder LEER los datos de la región secundaria en todo momento. ¿Qué eliges?", o: ["RA-GRS", "GRS", "ZRS", "LRS"], a: [0], e: "RA = read access. Con GRS normal la copia secundaria existe pero no la puedes leer hasta que haya una conmutación por error.", c: "\"leer desde la región secundaria\" = RA-GRS o RA-GZRS." },
  { id: "stor12", tp: "stor", q: "Quieres la máxima protección: copias en 3 zonas de tu región Y copia en la región par. ¿Qué redundancia es?", o: ["GZRS", "GRS", "ZRS", "LRS"], a: [0], e: "GZRS = ZRS en tu región + copia en la región par. Te protege de la caída de un edificio y de la caída de la región.", c: "\"zonas + otra región\" = GZRS." },
  { id: "stor13", tp: "stor", q: "¿Qué es cierto del nombre de una storage account?", o: ["Debe ser único en todo Azure, porque forma parte de su URL", "Solo debe ser único dentro del resource group", "Puede repetirse en otra región", "Puede tener mayúsculas y espacios"], a: [0], e: "La URL es tipo https://nombre.blob.core.windows.net, así que el nombre es global: de 3 a 24 caracteres, solo minúsculas y números.", c: "\"storage account name\" = único globalmente." },

  { id: "mover1", tp: "mover", q: "Quieres automatizar con un script la copia de archivos hacia Blob Storage desde la línea de comandos. ¿Qué herramienta usas?", o: ["AzCopy", "Azure Storage Explorer", "Azure File Sync", "Azure Data Box"], a: [0], e: "AzCopy es la utilidad de línea de comandos para copiar datos desde o hacia storage.", c: "\"línea de comandos\" o \"script\" = AzCopy." },
  { id: "mover2", tp: "mover", q: "Prefieres una aplicación con interfaz gráfica para ver y mover archivos de tus storage accounts. ¿Qué usas?", o: ["Azure Storage Explorer", "AzCopy", "Azure Migrate", "Azure Arc"], a: [0], e: "Storage Explorer es la app de escritorio (Windows, macOS, Linux). Por debajo usa AzCopy para las transferencias.", c: "\"interfaz gráfica\" = Storage Explorer." },
  { id: "mover3", tp: "mover", q: "Quieres mantener tu file server de Windows en la oficina, pero sincronizado con Azure Files y con caché local de lo más usado. ¿Qué usas?", o: ["Azure File Sync", "Azure Data Box", "AzCopy", "Azure Migrate"], a: [0], e: "File Sync convierte tu Windows Server en una caché de Azure Files. Es una sincronización continua, no una migración de una sola vez.", c: "\"sincronizar Windows Server con Azure Files\" = File Sync." },
  { id: "mover4", tp: "mover", q: "Necesitas evaluar tus servidores locales, estimar su costo en Azure y migrarlos. ¿Qué servicio es el punto central?", o: ["Azure Migrate", "Azure Data Box", "Azure File Sync", "Azure Advisor"], a: [0], e: "Azure Migrate es el centro de migración: descubre, evalúa y mueve servidores, bases de datos y apps.", c: "\"evaluar y migrar servidores\" = Azure Migrate." },
  { id: "mover5", tp: "mover", q: "Tienes 60 TB que mover a Azure y tu internet es lento. ¿Qué usas?", o: ["Azure Data Box", "AzCopy", "Azure File Sync", "VPN Gateway"], a: [0], e: "Data Box = Microsoft te manda un dispositivo físico, lo llenas y lo regresas por paquetería. A veces un camión es más rápido que internet.", c: "\"terabytes\" + \"ancho de banda limitado\" = Data Box." },

  { id: "ident1", tp: "ident", q: "¿Qué servicio administra identidades en la nube y el inicio de sesión en Microsoft 365, Azure y apps SaaS?", o: ["Microsoft Entra ID", "Microsoft Entra Domain Services", "Azure Policy", "Microsoft Purview"], a: [0], e: "Entra ID (antes Azure Active Directory) es el directorio de identidades en la nube: usuarios, grupos, inicio de sesión, MFA.", c: "\"identidad en la nube\" = Entra ID." },
  { id: "ident2", tp: "ident", q: "Una app antigua necesita unirse a un dominio y usar LDAP y Kerberos, pero no quieres administrar controladores de dominio. ¿Qué usas?", o: ["Microsoft Entra Domain Services", "Microsoft Entra ID", "Azure Arc", "Una VM con Windows Server"], a: [0], e: "Entra Domain Services te da un dominio administrado estilo Active Directory clásico (domain join, Group Policy, LDAP, Kerberos/NTLM) sin montar tus propios controladores.", c: "\"apps legacy\", \"domain join\", \"LDAP/Kerberos\" sin administrar DCs = Entra Domain Services." },
  { id: "ident3", tp: "ident", x: 1, q: "Los usuarios inician sesión una sola vez y acceden a varias aplicaciones sin volver a escribir su contraseña. ¿Qué es?", o: ["Single sign-on (SSO)", "Multifactor authentication (MFA)", "Conditional Access", "RBAC"], a: [0], e: "SSO = pulsera de todo incluido: te la ponen una vez y entras a todos los restaurantes. MFA es pedirte una prueba extra en un inicio de sesión.", c: "\"iniciar sesión una vez\" = SSO." },
  { id: "ident4", tp: "ident", q: "Además de la contraseña, se pide un código de la app Authenticator en el teléfono. ¿Qué es?", o: ["Multifactor authentication (MFA)", "Single sign-on", "Passwordless", "RBAC"], a: [0], e: "MFA combina factores de categorías distintas: algo que sabes (contraseña), algo que tienes (teléfono) o algo que eres (huella).", c: "\"segundo factor\" o \"código en el teléfono\" = MFA." },
  { id: "ident5", tp: "ident", q: "Los empleados entran con Windows Hello o una llave de seguridad FIDO2, sin escribir contraseña. ¿Qué método es?", o: ["Passwordless", "SSO", "MFA con SMS", "External identities"], a: [0], e: "Passwordless quita la contraseña y usa algo que tienes junto con biometría o PIN. Es más seguro y más cómodo.", c: "\"sin contraseña\", Windows Hello, FIDO2 o Authenticator = passwordless." },
  { id: "ident6", tp: "ident", q: "Un consultor de otra empresa necesita acceder a tus apps usando su propia cuenta corporativa. ¿Qué capacidad usas?", o: ["External identities (B2B)", "Entra Domain Services", "Azure Arc", "Resource locks"], a: [0], e: "External identities permite invitar a gente de fuera: entra con su identidad y tú controlas a qué accede.", c: "\"socios\", \"invitados\", \"su propia cuenta\" = External identities." },
  { id: "ident7", tp: "ident", q: "Quieres exigir MFA solo cuando alguien inicia sesión desde un país desconocido o un dispositivo no administrado. ¿Qué usas?", o: ["Microsoft Entra Conditional Access", "RBAC", "Azure Policy", "SSO"], a: [0], e: "Conditional Access es un si-entonces: SI (usuario, ubicación, dispositivo, riesgo) ENTONCES (permitir, pedir MFA o bloquear).", c: "\"según ubicación, dispositivo o riesgo\" = Conditional Access." },
  { id: "ident8", tp: "ident", q: "Un desarrollador debe ver los recursos de un resource group pero no modificarlos. ¿Qué usas?", o: ["Azure RBAC con el rol Reader", "Resource lock ReadOnly", "Azure Policy", "Conditional Access"], a: [0], e: "RBAC decide QUIÉN puede hacer QUÉ y DÓNDE. Un lock ReadOnly bloquearía los cambios para TODOS, no solo para esa persona.", c: "\"una persona\" + \"permisos\" = RBAC." },
  { id: "ident9", tp: "ident", q: "¿Cuál es la diferencia entre autenticación y autorización?", o: ["Autenticación comprueba quién eres; autorización decide qué puedes hacer", "Son lo mismo", "Autenticación decide permisos; autorización comprueba identidad", "Autorización solo existe en SaaS"], a: [0], e: "En el aeropuerto: mostrar tu INE es autenticación; tu pase de abordar decide a qué avión subes, y eso es autorización.", c: "AuthN = identidad (Entra ID, MFA). AuthZ = permisos (RBAC)." },
  { id: "ident10", tp: "ident", q: "¿Qué modelo asume que la red ya está comprometida y verifica explícitamente cada solicitud con el menor privilegio posible?", o: ["Zero Trust", "Defense-in-depth", "Responsabilidad compartida", "Perímetro de red"], a: [0], e: "Zero Trust = nunca confíes, siempre verifica. Tres principios: verificar explícitamente, menor privilegio y asumir la brecha.", c: "\"nunca confiar, siempre verificar\" o \"asumir brecha\" = Zero Trust." },
  { id: "ident11", tp: "ident", q: "¿Qué modelo protege con varias capas (seguridad física, identidad, perímetro, red, cómputo, aplicación, datos), de modo que si una falla, las demás frenan el ataque?", o: ["Defense-in-depth", "Zero Trust", "SSO", "Conditional Access"], a: [0], e: "Defense-in-depth = castillo con muralla, foso, guardias y bóveda. Los datos están en el centro.", c: "\"capas\" = defense-in-depth." },
  { id: "ident12", tp: "ident", q: "Quieres evaluar la postura de seguridad de tus recursos en Azure, on-premises y otras nubes, con recomendaciones y protección contra amenazas. ¿Qué usas?", o: ["Microsoft Defender for Cloud", "Azure Advisor", "Azure Service Health", "Microsoft Purview"], a: [0], e: "Defender for Cloud es seguridad: calificación de postura, recomendaciones y detección de amenazas, también fuera de Azure. Advisor da recomendaciones generales, no es la herramienta de seguridad dedicada.", c: "\"postura de seguridad\" o \"protección contra amenazas\" = Defender for Cloud." },

  { id: "costo1", tp: "costo", q: "¿Qué dos factores afectan el costo de un recurso en Azure?", o: ["El tipo de recurso y la región donde se despliega", "El consumo (cuánto lo usas)", "La cantidad de resource groups", "El número de tags aplicadas"], a: [0, 1], e: "Influyen el tipo y tamaño del recurso, el consumo, la región, el tráfico de red saliente y el tipo de suscripción. Organizar con resource groups o tags no cuesta.", c: "Costo = qué, cuánto, dónde y cuánto sale de Azure." },
  { id: "costo2", tp: "costo", q: "¿Qué transferencia de datos normalmente genera cobro en Azure?", o: ["Los datos que salen de Azure (egress)", "Los datos que entran a Azure (ingress)", "Los datos que se quedan en el mismo recurso", "Ninguna"], a: [0], e: "Entrar suele ser gratis; salir cuesta. Como el estacionamiento que te cobra al salir.", c: "\"ancho de banda de salida\" = cobro." },
  { id: "costo3", tp: "costo", q: "Antes de desplegar, quieres estimar cuánto costará al mes una solución con 3 VMs, una base de datos y storage. ¿Qué usas?", o: ["Pricing calculator", "Cost Management", "Azure Advisor", "Azure Monitor"], a: [0], e: "El pricing calculator estima ANTES de gastar. Cost Management analiza lo que YA gastaste. (El TCO calculator ya no está en el temario vigente.)", c: "\"estimar antes de desplegar\" = pricing calculator." },
  { id: "costo4", tp: "costo", q: "Quieres que te llegue una alerta cuando el gasto del mes llegue al 80% de un monto definido. ¿Qué usas?", o: ["Cost Management (budgets y alertas)", "Pricing calculator", "Azure Service Health", "Resource locks"], a: [0], e: "Cost Management permite analizar el gasto, crear presupuestos y recibir alertas. Un presupuesto avisa; no apaga los recursos por sí solo.", c: "\"presupuesto\", \"alerta de gasto\", \"analizar gasto actual\" = Cost Management." },
  { id: "costo5", tp: "costo", x: 1, q: "Quieres reportar costos por departamento y por proyecto sin mover los recursos de sus resource groups. ¿Qué usas?", o: ["Tags", "Resource groups nuevos", "Management groups", "Suscripciones nuevas"], a: [0], e: "Tags = etiquetas de la ropa: pares nombre/valor (depto: ventas) que puedes filtrar en los reportes de costo. Un recurso puede tener muchas tags.", c: "\"categorizar costos\" o \"sin mover recursos\" = tags." },
  { id: "costo6", tp: "costo", q: "Aplicas una tag a un resource group. ¿Qué pasa con los recursos que contiene?", o: ["No heredan la tag automáticamente", "Heredan la tag siempre", "Se mueven a otro grupo", "Pierden sus tags propias"], a: [0], e: "Las tags no se heredan por defecto. Si quieres forzarlo, usas Azure Policy.", c: "Tags no se heredan (salvo que lo fuerce una policy)." },
  { id: "costo7", tp: "costo", q: "Ya tienes licencias de Windows Server y SQL Server con Software Assurance y quieres reutilizarlas en Azure para pagar menos. ¿Qué beneficio usas?", o: ["Azure Hybrid Benefit", "Spot VMs", "Free account", "Pay-as-you-go"], a: [0], e: "Azure Hybrid Benefit te deja traer tus licencias existentes para no pagarlas dos veces.", c: "\"reutilizar licencias existentes\" = Azure Hybrid Benefit." },

  { id: "gob1", tp: "gob", q: "Quieres descubrir, clasificar y catalogar los datos de tu organización en Azure, en tu datacenter y en otras nubes. ¿Qué usas?", o: ["Microsoft Purview", "Azure Policy", "Azure RBAC", "Azure Monitor"], a: [0], e: "Purview gobierna los DATOS: dónde están, qué tan sensibles son y quién los usa. No gobierna cómo se crean los recursos; eso es Policy.", c: "\"catalogar\" o \"clasificar datos sensibles\" = Purview." },
  { id: "gob2", tp: "gob", q: "Quieres impedir que alguien cree recursos fuera de las regiones permitidas. ¿Qué usas?", o: ["Azure Policy", "RBAC", "Resource lock", "Microsoft Purview"], a: [0], e: "Policy = reglamento de construcción: define qué SÍ puede existir y cómo debe configurarse. RBAC en cambio define quién puede actuar.", c: "\"asegurar que todos los recursos cumplan una regla\" = Azure Policy." },
  { id: "gob3", tp: "gob", q: "Asignas una nueva Azure Policy y ya existen recursos que no la cumplen. ¿Qué pasa?", o: ["Se marcan como no conformes para que los revises o corrijas", "Se eliminan automáticamente", "Se mueven a otra suscripción", "La policy no se puede asignar"], a: [0], e: "Policy evalúa lo existente y lo reporta como no conforme. Lo nuevo que no cumpla se puede bloquear, y algunas policies permiten remediar.", c: "Policy no borra: evalúa, reporta y bloquea lo nuevo." },
  { id: "gob4", tp: "gob", q: "¿Cómo se llama un conjunto de varias Azure Policies agrupadas para un objetivo (por ejemplo, cumplir una norma)?", o: ["Initiative (iniciativa)", "Management group", "Blueprint de RBAC", "Resource lock"], a: [0], e: "Una initiative agrupa policies para asignarlas juntas.", c: "\"grupo de policies\" = initiative." },
  { id: "gob5", tp: "gob", q: "Quieres evitar que alguien borre por accidente la base de datos de producción, aunque tenga permisos de Owner. ¿Qué usas?", o: ["Un resource lock", "Azure Policy", "RBAC", "Tags"], a: [0], e: "Lock = candado físico: no importa quién seas, primero hay que quitar el candado. Aplica incluso a los Owners.", c: "\"evitar borrado accidental\" = resource lock." },
  { id: "gob6", tp: "gob", q: "¿Qué lock permite leer y modificar un recurso, pero no eliminarlo?", o: ["Delete (CanNotDelete)", "ReadOnly", "Policy deny", "Reader"], a: [0], e: "Hay dos: Delete (puedes usar y cambiar, no borrar) y ReadOnly (solo leer; ni cambiar ni borrar).", c: "\"no borrar pero sí modificar\" = Delete lock." },
  { id: "gob7", tp: "gob", x: 1, q: "¿En qué nivel NO puedes aplicar un resource lock?", o: ["Management group", "Suscripción", "Resource group", "Recurso individual"], a: [0], e: "Los locks se aplican a suscripción, resource group o recurso, y se heredan hacia abajo. No existen en management groups.", c: "Locks = suscripción, resource group o recurso." },
  { id: "gob8", tp: "gob", q: "Un Owner intenta eliminar un recurso que tiene un lock Delete. ¿Qué pasa?", o: ["La eliminación falla hasta que se quite el lock", "Se elimina porque es Owner", "Se elimina y el lock se mueve", "Azure pide MFA y lo elimina"], a: [0], e: "El lock gana sobre los permisos. Un Owner puede quitar el lock, pero tiene que hacerlo a propósito antes de borrar.", c: "Lock > RBAC para borrar." },

  { id: "admin1", tp: "admin", x: 1, q: "¿Qué capa de Azure recibe TODAS las solicitudes, vengan del portal, la CLI, PowerShell o un SDK?", o: ["Azure Resource Manager (ARM)", "Azure CLI", "Azure Cloud Shell", "Azure Arc"], a: [0], e: "ARM es el conmutador central: portal, CLI y PowerShell son teléfonos distintos, pero todas las llamadas pasan por ARM, que autentica, autoriza y ejecuta.", c: "\"capa de administración\" o \"servicio de implementación\" = ARM." },
  { id: "admin2", tp: "admin", x: 1, q: "¿Cómo accedes a Azure Cloud Shell?", o: ["Desde el navegador (portal), con Bash o PowerShell ya autenticado", "Solo instalándolo en tu computadora", "Solo desde una VM en Azure", "Solo con Azure Arc"], a: [0], e: "Cloud Shell es una terminal en el navegador, con la CLI y PowerShell listas y tu sesión ya iniciada. No instalas nada.", c: "\"desde el navegador\" = Cloud Shell." },
  { id: "admin3", tp: "admin", x: 1, q: "¿Qué dos cosas puedes hacer desde el Azure portal?", o: ["Crear recursos", "Crear usuarios en Microsoft Entra ID", "Cambiar la availability zone de una VM que ya existe", "Mover una región de Azure a otra geografía"], a: [0, 1], e: "El portal es la interfaz web para casi todo. Pero la zona de una VM se fija al crearla: para cambiarla hay que recrear o migrar la VM.", c: "La AZ de una VM no se cambia después de crearla." },
  { id: "admin4", tp: "admin", q: "¿Qué diferencia hay entre Azure CLI y Azure PowerShell?", o: ["La CLI usa comandos az; PowerShell usa cmdlets (Verbo-Sustantivo). Ambos corren en Windows, macOS y Linux", "La CLI solo funciona en Linux", "PowerShell solo funciona dentro de Cloud Shell", "Hacen cosas distintas: la CLI no puede crear recursos"], a: [0], e: "Hacen lo mismo con sintaxis distinta: az vm create contra New-AzVM. Eliges según tu costumbre.", c: "\"az ...\" = CLI. \"New-AzVM\" = PowerShell." },
  { id: "admin5", tp: "admin", q: "Quieres administrar servidores en tu datacenter y en AWS con las mismas herramientas de Azure (Policy, RBAC, monitoreo). ¿Qué usas?", o: ["Azure Arc", "Azure Migrate", "ExpressRoute", "Azure Virtual Desktop"], a: [0], e: "Arc extiende el control de Azure a lo que vive FUERA de Azure, sin migrarlo. Migrate, en cambio, lo mueve a Azure.", c: "\"administrar recursos fuera de Azure desde Azure\" = Arc." },
  { id: "admin6", tp: "admin", q: "Defines tu infraestructura en archivos versionados en Git para desplegar exactamente igual en desarrollo y producción. ¿Qué práctica es?", o: ["Infraestructura como código (IaC)", "Lift-and-shift", "Serverless", "Defense-in-depth"], a: [0], e: "IaC = receta escrita: cualquiera la sigue y sale el mismo platillo, sin clics manuales.", c: "\"repetible\", \"versionado\", \"en archivos\" = IaC." },
  { id: "admin7", tp: "admin", q: "¿Cómo son las ARM templates?", o: ["Declarativas: describes el estado final en JSON y ARM se encarga de los pasos", "Imperativas: escribes cada comando en orden", "Solo sirven para VMs", "Un tipo de resource lock"], a: [0], e: "Declarativo = pedir \"quiero una pizza hawaiana\", no explicar cómo hornearla. Bicep es un lenguaje más legible que se convierte a ARM template.", c: "\"JSON\" o \"Bicep\" + \"declarativo\" = ARM templates." },

  { id: "mon1", tp: "monitor", q: "Quieres recomendaciones personalizadas para reducir costos y mejorar la seguridad, la confiabilidad y el rendimiento de tus recursos. ¿Qué usas?", o: ["Azure Advisor", "Azure Service Health", "Azure Monitor", "Pricing calculator"], a: [0], e: "Advisor = el mecánico que revisa tu coche y te dice qué mejorar. No vigila en tiempo real; analiza y recomienda.", c: "\"recomendaciones\" = Advisor." },
  { id: "mon2", tp: "monitor", x: 1, q: "Quieres saber si hay mantenimiento planeado o una interrupción de Azure que afecte a tus servicios en tu región. ¿Qué usas?", o: ["Azure Service Health", "Log Analytics", "Application Insights", "Azure Advisor"], a: [0], e: "Service Health mira la salud de AZURE (del lado de Microsoft), filtrada a tus suscripciones y regiones: incidentes, mantenimiento planeado y avisos.", c: "\"interrupción de Azure\" o \"mantenimiento planeado\" = Service Health." },
  { id: "mon3", tp: "monitor", x: 1, q: "Quieres detectar anomalías de rendimiento y errores en tu aplicación web. ¿Qué usas?", o: ["Application Insights", "Azure Service Health", "Azure Advisor", "Azure DevOps"], a: [0], e: "Application Insights (parte de Azure Monitor) mide TU app: tiempos de respuesta, fallas, dependencias y anomalías.", c: "\"rendimiento de mi aplicación\" = Application Insights." },
  { id: "mon4", tp: "monitor", q: "Quieres recopilar métricas y logs de tus recursos y recibir una notificación cuando el CPU de una VM pase de 80%. ¿Qué usas?", o: ["Azure Monitor con alertas", "Azure Advisor", "Azure Service Health", "Microsoft Purview"], a: [0], e: "Azure Monitor es la plataforma de métricas y logs de TUS recursos. Las alerts disparan correos, SMS o acciones automáticas.", c: "\"métricas\", \"umbral\", \"alerta\" = Azure Monitor." },
  { id: "mon5", tp: "monitor", q: "Quieres escribir consultas sobre los logs recopilados para investigar un problema. ¿Qué herramienta de Azure Monitor usas?", o: ["Log Analytics", "Application Insights", "Azure Advisor", "Cost Management"], a: [0], e: "Log Analytics es donde consultas los logs con KQL (Kusto Query Language).", c: "\"consultar logs\" o \"KQL\" = Log Analytics." },
  // --- Preguntas agregadas el 17-sep-2026 para emparejar el dominio 3 y ampliar storage.
  // Verificadas contra learn.microsoft.com: access-tiers-overview (act. jun-2026) y lock-resources (act. abr-2026).
  { id: "gob9", tp: "gob", q: "Un recurso tiene un lock de tipo Delete y alguien intenta eliminar todo el resource group que lo contiene. ¿Qué pasa?", o: ["Falla la eliminación completa: no se borra nada del grupo", "Se borra el resto del grupo y se conserva solo el recurso bloqueado", "Se borra todo, porque el lock solo aplica al recurso", "Azure pide confirmación y luego borra todo"], a: [0], e: "El lock bloquea la operación entera. No existe la eliminación parcial: si un solo recurso del grupo está protegido, la eliminación del grupo falla.", c: "Un lock adentro detiene el borrado de todo el grupo." },
  { id: "gob10", tp: "gob", q: "¿Quién puede crear o quitar un resource lock?", o: ["Owner y User Access Administrator", "Cualquiera con rol Contributor", "Solo el administrador de facturación", "Cualquiera con rol Reader"], a: [0], e: "Crear o borrar locks requiere permisos sobre Microsoft.Authorization/locks. Los roles integrados que los traen son Owner y User Access Administrator. Contributor crea recursos, pero no administra locks.", c: "Locks = Owner o User Access Administrator." },
  { id: "gob11", tp: "gob", q: "Una storage account tiene un lock ReadOnly. ¿Protege eso los blobs que contiene de ser borrados?", o: ["No: los locks aplican al plano de control, no al de datos", "Sí, ningún dato puede borrarse", "Sí, pero solo si además se activa el borrado temporal", "Solo protege los blobs del tier Archive"], a: [0], e: "Los locks solo cubren operaciones del plano de control, que van a management.azure.com. Borrar un blob es una operación del plano de datos y el lock no la toca. Para los datos se usan otras protecciones, como el borrado temporal.", c: "Lock = protege el recurso, no los datos adentro." },
  { id: "gob12", tp: "gob", q: "En el portal los locks se llaman Delete y Read-only. ¿Cómo se llaman esos mismos niveles desde la CLI o la API?", o: ["CanNotDelete y ReadOnly", "NoDelete y Readable", "Protected y Frozen", "DenyDelete y DenyWrite"], a: [0], e: "Es el mismo lock con dos nombres según dónde se cree: en el portal, Delete y Read-only; en línea de comandos y API, CanNotDelete y ReadOnly.", c: "Portal: Delete. CLI: CanNotDelete." },
  { id: "gob13", tp: "gob", q: "Microsoft Purview está configurado en la organización, pero no reporta nada de una base de datos que sí existe. ¿Cuál es la causa más probable?", o: ["Esa fuente de datos no está registrada ni se le dio acceso a Purview", "Purview solo funciona con datos dentro de Azure", "Purview solo cataloga archivos, no bases de datos", "Falta activar el nivel premium de la suscripción"], a: [0], e: "Purview escanea únicamente las fuentes que alguien registra y para las que se le dan credenciales. Puede cubrir Azure, servidores locales, otras nubes y SaaS, pero nada de eso ocurre solo.", c: "Purview cataloga lo que se le registra, no lo que existe." },
  { id: "costo8", tp: "costo", q: "¿Qué herramienta muestra informes históricos de gasto y un pronóstico del consumo futuro?", o: ["Cost Management", "Pricing calculator", "Azure Advisor", "Azure Monitor"], a: [0], e: "Cost Management trabaja con el gasto real: análisis, presupuestos, alertas, informes históricos y pronóstico basado en ese consumo. El pricing calculator solo estima algo que todavía no existe.", c: "Pronóstico sobre gasto real = Cost Management." },
  { id: "costo9", tp: "costo", q: "Una alerta avisa que el gasto del mes llegó al 80 % del monto definido. ¿De dónde sale esa alerta?", o: ["De un budget de Cost Management", "De una alerta de Azure Monitor", "De Azure Advisor", "De Service Health"], a: [0], e: "Las alertas de dinero salen de los budgets de Cost Management. Azure Monitor alerta sobre el comportamiento técnico de los recursos, como el uso de CPU.", c: "Si la alerta habla de pesos, es Cost Management." },
  { id: "mon6", tp: "monitor", q: "Quieres saber si una máquina virtual tuya está caída por un problema de la plataforma de Azure y no por tu configuración. ¿Qué revisas?", o: ["Resource Health", "Azure status", "Azure Advisor", "Log Analytics"], a: [0], e: "Los tres niveles van de lo general a lo particular: Azure status informa del estado global, Service Health filtra lo que afecta a tus suscripciones y regiones, y Resource Health responde por un recurso concreto tuyo.", c: "Un recurso específico afectado por Azure = Resource Health." },
  { id: "mon7", tp: "monitor", x: 1, q: "¿En cuántas categorías da recomendaciones Azure Advisor?", o: ["Cinco: confiabilidad, seguridad, rendimiento, costo y excelencia operativa", "Dos: costo y seguridad", "Tres: costo, rendimiento y disponibilidad", "Una: optimización de costos"], a: [0], e: "Advisor cubre cinco pilares. Por eso aparece en preguntas de costo y de seguridad, aunque no sea la herramienta especializada de ninguna de las dos.", c: "Advisor: cinco pilares, ninguna especialidad." },
  { id: "admin8", tp: "admin", q: "¿Qué relación hay entre Bicep y las plantillas ARM?", o: ["Bicep es un lenguaje más legible que se convierte en una plantilla ARM", "Bicep sustituye a ARM y despliega por su cuenta", "Bicep solo sirve para redes y ARM para lo demás", "Son lo mismo con distinto nombre comercial"], a: [0], e: "Bicep describe la misma infraestructura con menos ruido que el JSON y se transpila a una plantilla ARM. Los dos son declarativos: describen el estado final, no los pasos.", c: "Bicep se compila a ARM; los dos son declarativos." },

  { id: "stor14", tp: "stor", q: "¿Cuál es el periodo mínimo recomendado de permanencia en los tiers Cool, Cold y Archive?", o: ["30, 90 y 180 días", "7, 30 y 90 días", "30, 60 y 120 días", "No hay mínimos, solo diferencias de precio"], a: [0], e: "Cool pide 30 días, Cold 90 y Archive 180. Sacar o mover un blob antes genera un cargo por eliminación temprana, prorrateado por los días que faltaban.", c: "30, 90 y 180: Cool, Cold y Archive." },
  { id: "stor15", tp: "stor", q: "Necesitas leer un blob que está en el tier Archive. ¿Qué tienes que hacer y cuánto puede tardar?", o: ["Rehidratarlo a un tier en línea; puede tardar hasta 15 horas", "Nada especial: se lee igual que en Cool", "Moverlo a otra storage account, lo que tarda minutos", "Solicitar acceso al soporte de Azure"], a: [0], e: "Archive está fuera de línea: el blob no se puede leer ni modificar hasta rehidratarlo a Hot, Cool o Cold. La rehidratación admite prioridad estándar o alta, y puede tardar hasta 15 horas.", c: "Archive no se lee: primero se rehidrata." },
  { id: "stor16", tp: "stor", q: "¿Qué tier de acceso NO puede quedar como valor por defecto de una storage account?", o: ["Archive", "Hot", "Cool", "Cold"], a: [0], e: "El tier por defecto de la cuenta puede ser Hot, Cool o Cold. Archive se asigna blob por blob, nunca como valor por defecto, y además solo está disponible en cuentas LRS, GRS y RA-GRS.", c: "Archive se pone por blob, nunca por defecto." },
  // --- Segunda tanda del 17-sep-2026. Monitor verificado contra azure-monitor/fundamentals/overview (act. jun-2026).
  { id: "nube6", tp: "nube", q: "Una empresa corre parte de su plataforma en Azure y parte en otro proveedor de nube pública, sin conectarlas entre sí. ¿Qué modelo describe eso?", o: ["Multinube", "Nube híbrida", "Nube privada", "Nube comunitaria"], a: [0], e: "Multinube es usar más de un proveedor de nube pública. Híbrida es combinar nube pública con infraestructura propia o privada, conectadas entre sí.", c: "Dos proveedores de nube pública = multinube. Nube más on-premises = híbrida." },
  { id: "nube7", tp: "nube", q: "Un estudio de videojuegos lanza un título nuevo y no sabe si tendrá mil o un millón de jugadores el primer día. ¿Qué modelo de nube le conviene?", o: ["Pública, por la capacidad disponible sin comprar hardware", "Privada, para controlar el hardware", "Ninguno: necesita servidores propios", "Híbrida, obligatoriamente"], a: [0], e: "La nube pública resuelve justo la demanda impredecible: la capacidad ya está comprada y se paga conforme se usa. Con hardware propio habría que adivinar el pico y pagarlo por adelantado.", c: "Demanda impredecible y sin inversión inicial = pública." },
  { id: "resp6", tp: "resp", q: "Una empresa usa Microsoft 365. ¿Quién decide qué empleados tienen acceso a cada archivo?", o: ["La empresa, porque las cuentas y los accesos siempre son del cliente", "Microsoft, porque administra la aplicación", "Se reparte por igual entre ambos", "El proveedor de identidad externo"], a: [0], e: "Aun en SaaS, las cuentas, las identidades y quién accede a qué son responsabilidad del cliente. Microsoft opera la aplicación y la infraestructura, no decide los permisos internos de la organización.", c: "Cuentas, accesos y datos: siempre del cliente." },
  { id: "benef10", tp: "benef", q: "¿Qué ventaja de seguridad ofrece la nube frente a mantener servidores propios?", o: ["El proveedor aplica los parches de la infraestructura y ofrece herramientas de cumplimiento integradas", "Elimina por completo la posibilidad de un ataque", "Hace innecesario controlar los accesos de los usuarios", "Cifra automáticamente todos los datos sin configuración alguna"], a: [0], e: "La nube quita de encima el mantenimiento de la infraestructura física y aporta herramientas de seguridad y cumplimiento listas para usar. Lo que no quita es la responsabilidad del cliente sobre datos, identidades y accesos.", c: "La nube reduce trabajo de seguridad; no lo elimina." },
  { id: "benef11", tp: "benef", q: "¿Qué diferencia hay entre escalabilidad y elasticidad?", o: ["Escalabilidad es poder crecer; elasticidad es que ese ajuste ocurra solo según la demanda", "Son sinónimos", "Escalabilidad aplica a datos y elasticidad a cómputo", "Elasticidad es crecer y escalabilidad es reducir"], a: [0], e: "Un sistema escalable admite más carga si se le agregan recursos. Elástico significa que esos recursos se agregan y se quitan automáticamente conforme sube o baja la demanda.", c: "Puede crecer = escalable. Crece y se encoge solo = elástico." },
  { id: "tipos7", tp: "tipos", q: "Una empresa contrata un sistema de nómina ya terminado, al que solo entra por navegador y paga por usuario al mes. ¿Qué tipo de servicio es?", o: ["SaaS", "PaaS", "IaaS", "Nube privada"], a: [0], e: "Es software terminado, operado por el proveedor, que se consume con una suscripción. El cliente no escribe código ni administra servidores: solo configura y usa.", c: "Software listo + suscripción por usuario = SaaS." },
  { id: "precio8", tp: "precio", q: "Una empresa necesita máquinas para un proceso nocturno que puede reanudarse si se interrumpe, y busca el precio más bajo. ¿Qué opción de compra encaja?", o: ["Spot", "Reservations a tres años", "Pay-as-you-go", "Azure Hybrid Benefit"], a: [0], e: "Spot aprovecha capacidad sobrante a precio bajo, y Azure puede reclamarla cuando la necesite. Sirve cuando el trabajo tolera interrupciones. Las reservas piden compromiso de uno o tres años sobre cargas estables.", c: "Interrumpible y barato = Spot. Estable y con compromiso = reservations." },

  { id: "monitor8", tp: "monitor", q: "El escalado automático que agrega o quita recursos según la carga, ¿de qué servicio forma parte?", o: ["Azure Monitor", "Azure Advisor", "Azure Policy", "Azure Arc"], a: [0], e: "Autoscale es una capacidad de Azure Monitor: las reglas se definen sobre métricas, horarios o ambos, y por eso vive donde viven las métricas.", c: "Autoscale se apoya en métricas, y las métricas son de Monitor." },
  { id: "monitor9", tp: "monitor", q: "Una alerta de Azure Monitor se disparó. ¿Qué define a quién se le avisa y qué se ejecuta en respuesta?", o: ["Un action group", "Un resource lock", "Una Azure Policy", "Un budget"], a: [0], e: "Los action groups agrupan las acciones de respuesta de una alerta: notificar por correo o SMS, llamar un webhook, ejecutar un runbook de Automation o un flujo de Logic Apps.", c: "La alerta detecta; el action group responde." },
  { id: "monitor10", tp: "monitor", q: "Tienes servidores en tu centro de datos y en otra nube, y quieres monitorearlos junto con los de Azure. ¿Qué combinación lo permite?", o: ["Azure Arc para conectarlos y Azure Monitor para observarlos", "Solo Azure Monitor, sin nada más", "Azure Migrate y Service Health", "Defender for Cloud y Cost Management"], a: [0], e: "Azure Monitor puede ser el monitoreo central de entornos híbridos, pero primero hay que incorporar esos recursos con Azure Arc para que Azure los vea.", c: "Arc los conecta; Monitor los observa." },
  { id: "admin9", tp: "admin", q: "Además de crear recursos, ¿qué otras tareas pasan por Azure Resource Manager?", o: ["Aplicar control de acceso, locks y etiquetas sobre los recursos", "Ejecutar el código de las aplicaciones", "Facturar el consumo mensual", "Analizar los logs de seguridad"], a: [0], e: "ARM es la capa de administración: cada solicitud pasa por ahí, venga del portal, la CLI, PowerShell o un SDK, y ahí se autentica, se autoriza y se aplican funciones como RBAC, locks y tags.", c: "Todo lo que administra recursos pasa por ARM." },
  { id: "gob14", tp: "gob", q: "La organización quiere que ningún recurso pueda crearse sin la etiqueta del departamento responsable. ¿Qué lo hace cumplir?", o: ["Azure Policy", "Un resource lock", "RBAC", "Microsoft Purview"], a: [0], e: "Las tags por sí solas no se imponen ni se heredan del resource group. Para exigirlas se usa Azure Policy, que puede bloquear la creación de recursos que no cumplan la regla o incluso agregar la etiqueta.", c: "Obligar una regla al crear recursos = Policy." },
  { id: "gob15", tp: "gob", q: "¿Qué diferencia principal hay entre Azure Policy y RBAC?", o: ["Policy controla qué se puede crear y cómo; RBAC controla quién puede actuar", "Policy es para suscripciones y RBAC para recursos", "Policy sustituye a RBAC en management groups", "Son dos nombres del mismo mecanismo"], a: [0], e: "Policy evalúa propiedades de los recursos: regiones permitidas, tamaños, etiquetas obligatorias. RBAC asigna permisos a personas, grupos o aplicaciones en un ámbito. Un Owner puede quedar bloqueado por una Policy.", c: "Policy = qué puede existir. RBAC = quién puede actuar." },
  { id: "costo10", tp: "costo", q: "Una máquina virtual de pruebas se deja detenida pero sin desasignar durante el fin de semana. ¿Qué pasa con el costo?", o: ["Sigue generando cargos, porque los recursos permanecen reservados", "Deja de costar por completo al apagarse", "Solo se cobra el disco, nunca el cómputo", "El costo se reembolsa automáticamente"], a: [0], e: "Apagar desde el sistema operativo no libera los recursos: la máquina sigue asignada y facturando. Además, los discos administrados se cobran aunque la máquina esté desasignada. El mantenimiento de lo que ya no se usa es uno de los factores que encarecen la factura.", c: "Detener no es desasignar; y el disco se paga aparte." },
  // --- Tercera tanda del 17-sep-2026: cerrar la proporción de dominios.
  { id: "nube8", tp: "nube", q: "¿Qué es lo que define a una nube privada frente a una pública?", o: ["El uso exclusivo de una sola organización, esté donde esté el hardware", "Que el hardware viva forzosamente en las oficinas de la empresa", "Que no tenga conexión a internet", "Que la administre siempre un tercero"], a: [0], e: "Lo que la define es la exclusividad, no la ubicación: una nube privada puede vivir en el centro de datos de la organización o estar hospedada por un tercero, pero la usa una sola organización.", c: "Privada = exclusiva. Pública = compartida y disponible para cualquiera." },
  { id: "resp7", tp: "resp", q: "En un despliegue on-premises tradicional, ¿de quién es la responsabilidad del sistema operativo, la red física y los datos?", o: ["Toda del cliente", "Toda del proveedor", "Compartida por partes iguales", "Del cliente, salvo la red física"], a: [0], e: "On-premises no hay proveedor que comparta nada: edificio, hardware, red, sistema operativo, aplicaciones y datos son de la organización. El modelo de responsabilidad compartida empieza justo cuando algo se renta.", c: "On-premises: todo es tuyo, incluido el trabajo." },
  { id: "tipos8", tp: "tipos", q: "Un equipo desarrolla y mantiene su propia aplicación, quiere publicarla sin administrar servidores y necesita que escale sola. ¿Qué tipo de servicio encaja?", o: ["PaaS", "SaaS", "IaaS", "On-premises"], a: [0], e: "La aplicación es del equipo, así que SaaS queda descartado. Y como no quieren administrar servidores ni sistema operativo, tampoco es IaaS.", c: "App propia + sin administrar servidores = PaaS." },
  { id: "benef12", tp: "benef", q: "Una empresa configura escalado automático y balanceo de carga para que su sitio responda igual de rápido en días normales y en rebajas. ¿Qué beneficio busca?", o: ["Previsibilidad del rendimiento", "Gobernanza", "Previsibilidad del costo", "Capacidad de administración"], a: [0], e: "La previsibilidad tiene dos caras: de costo, con herramientas de estimación y reservas, y de rendimiento, con autoescalado y balanceo para sostener la experiencia bajo distintas cargas.", c: "Rendimiento parejo pase lo que pase = previsibilidad." },
  { id: "benef13", tp: "benef", q: "Un equipo despliega todos sus ambientes con plantillas versionadas para que cumplan los mismos estándares corporativos. ¿Qué beneficio de la nube ejemplifica?", o: ["Gobernanza", "Elasticidad", "Alta disponibilidad", "Agilidad"], a: [0], e: "Gobernanza es que todo lo que se crea cumpla las reglas de la organización. Las plantillas y las políticas son las herramientas que la hacen posible sin revisar recurso por recurso.", c: "Estándares que se cumplen solos = gobernanza." },
  { id: "precio9", tp: "precio", q: "¿Qué ofrece la cuenta gratuita de Azure?", o: ["Un crédito por tiempo limitado, servicios populares gratis durante los primeros meses y algunos servicios siempre gratuitos", "Acceso ilimitado a cualquier servicio sin costo", "Un descuento permanente del 50 %", "Solo acceso al portal, sin crear recursos"], a: [0], e: "La cuenta gratuita mezcla tres cosas: un crédito inicial con vigencia, un conjunto de servicios gratis durante los primeros meses y una lista de servicios que siempre tienen una capa sin costo. Pasado eso, se cobra como en cualquier suscripción.", c: "Cuenta gratuita: crédito con fecha, no barra libre." },

  { id: "admin10", tp: "admin", q: "Ejecutas la misma plantilla ARM dos veces seguidas sobre el mismo resource group. ¿Qué ocurre?", o: ["El resultado es el mismo: lo que ya existe y coincide no se duplica", "Se crean recursos duplicados con otro nombre", "La segunda ejecución falla siempre", "Se borra todo y se vuelve a crear"], a: [0], e: "Las plantillas son declarativas e idempotentes: describen el estado final deseado. ARM compara con lo que existe y solo aplica lo que falta, así que repetir el despliegue no duplica recursos.", c: "Declarativo e idempotente: describe el resultado, no los pasos." },
  { id: "admin11", tp: "admin", q: "Una empresa quiere seguir operando sus servidores en su propio centro de datos, pero aplicarles las políticas y el monitoreo de Azure. ¿Qué usa?", o: ["Azure Arc", "Azure Migrate", "Azure Virtual Desktop", "ExpressRoute"], a: [0], e: "Arc extiende la administración de Azure a servidores que se quedan fuera de Azure. Migrate hace lo contrario: los mueve a Azure.", c: "Quedarse afuera y ser administrado desde Azure = Arc." },
  { id: "monitor11", tp: "monitor", q: "¿Qué diferencia hay entre métricas y logs en Azure Monitor?", o: ["Las métricas son valores numéricos tomados a intervalos; los logs son registros con detalle que se consultan con KQL", "Las métricas son de aplicaciones y los logs de infraestructura", "Las métricas se guardan para siempre y los logs una semana", "Son lo mismo con distinta interfaz"], a: [0], e: "Las métricas son series numéricas ligeras, buenas para alertas y gráficas en tiempo casi real. Los logs guardan eventos con contexto en un workspace de Log Analytics y se investigan con consultas KQL.", c: "Números en el tiempo = métricas. Eventos con detalle = logs." },
  { id: "gob16", tp: "gob", q: "Una Azure Policy con efecto de denegación se asigna a una suscripción donde ya existen recursos que no la cumplen. ¿Qué pasa con esos recursos?", o: ["Siguen existiendo y se reportan como no conformes", "Se eliminan automáticamente", "Se corrigen solos de inmediato", "La asignación de la policy falla"], a: [0], e: "Policy evalúa lo existente y lo marca como no conforme, y bloquea lo nuevo que rompa la regla. Corregir lo viejo es una tarea aparte, que algunas policies permiten automatizar con remediación.", c: "Policy no borra: reporta lo viejo y bloquea lo nuevo." },
  { id: "costo11", tp: "costo", q: "¿Cuál de estos factores NO cambia lo que se paga en Azure?", o: ["La cantidad de resource groups que se usen para organizar", "La región donde se despliega el recurso", "El tráfico de salida hacia internet", "El tipo y tamaño del recurso"], a: [0], e: "Organizar con resource groups o etiquetas no cuesta: son contenedores lógicos y metadatos. Lo que mueve la factura es qué recurso se usa, cuánto, en qué región y cuántos datos salen.", c: "Organizar es gratis; consumir es lo que cuesta." },
  { id: "costo12", tp: "costo", q: "Una empresa compra en Azure Marketplace una solución de un proveedor externo. ¿Qué implica en la factura?", o: ["Se paga tanto el consumo de Azure como lo que cobre ese proveedor", "Solo se paga el consumo de Azure", "Marketplace siempre es gratuito", "El cargo del proveedor lo absorbe Microsoft"], a: [0], e: "Las ofertas de Marketplace son de terceros y tienen su propio precio, que aparece en la misma factura además del consumo de la infraestructura de Azure que utilicen.", c: "Marketplace suma el costo del tercero." },
  { id: "geo8", tp: "geo", q: "¿Cómo se relacionan una región, una availability zone y un datacenter?", o: ["La región es un conjunto de instalaciones físicas con uno o más datacenters, y una availability zone es un grupo de datacenters con energía, enfriamiento y red aislados dentro de esa región", "El datacenter contiene varias regiones y cada región tiene una availability zone", "Región, availability zone y datacenter son tres nombres para lo mismo", "La availability zone es un datacenter y la región es un rack dentro de ese datacenter"], a: [0], e: "Una región de Azure está formada por uno o más datacenters conectados por una red de baja latencia, y suelen estar dentro de una misma área metropolitana. Las availability zones son conjuntos independientes de datacenters, cada uno con energía, enfriamiento y conectividad propios. Al desplegar eliges región y zona; el datacenter no se elige.", c: "La región agrupa datacenters. La zona agrupa datacenters con energía, enfriamiento y red aislados." },
  { id: "ident13", tp: "ident", q: "Un proveedor externo necesita entrar a una aplicación de la empresa usando la cuenta corporativa que ya tiene, sin que le creen credenciales nuevas. ¿Qué se usa?", o: ["B2B collaboration de Microsoft Entra External ID", "Crearle una cuenta de empleado en el directorio", "Compartir una cuenta de servicio con varios proveedores", "Microsoft Entra Domain Services"], a: [0], e: "En B2B collaboration los invitados de negocio no tienen credenciales en tu directorio: se autentican con su organización de origen o con su proveedor de identidad. Sí se les crea un objeto de usuario en el mismo directorio de los empleados, para poder darles permisos y agregarlos a grupos.", c: "Socio externo que entra con su propia identidad: B2B collaboration." },
  { id: "ident14", tp: "ident", q: "¿En qué momento se aplica una política de Conditional Access?", o: ["Después de que se completa la autenticación de primer factor", "Antes de cualquier autenticación, como primera barrera de la red", "Solo al cerrar sesión", "Únicamente cuando el usuario cambia su contraseña"], a: [0], e: "Conditional Access reúne señales (usuario, ubicación, dispositivo, aplicación y riesgo), toma una decisión y la aplica, pero corre después del primer factor. Por eso Microsoft aclara que no está pensado como defensa de primera línea ante ataques de denegación de servicio. Requiere licencia Microsoft Entra ID P1.", c: "Primero demuestras quién eres; luego Conditional Access decide qué más te pide." },
  { id: "ident15", tp: "ident", q: "¿Cuáles son los tres principios de Zero Trust?", o: ["Verificar explícitamente, usar privilegio mínimo y asumir la brecha", "Cifrar todo, respaldar a diario y rotar contraseñas", "Confiar en la red interna, revisar el perímetro y auditar al final del mes", "Autenticar una vez, mantener la sesión abierta y registrar accesos"], a: [0], e: "Zero Trust parte de nunca confiar y siempre verificar. Verificar explícitamente significa autenticar y autorizar cada petición con todas las señales disponibles; privilegio mínimo, dar solo el acceso necesario y por el menor tiempo posible; asumir la brecha, diseñar los controles dando por hecho que puede haber un atacante dentro.", c: "Verificar explícitamente, privilegio mínimo, asumir la brecha." },
  { id: "ident16", tp: "ident", q: "¿Qué indica el secure score de Microsoft Defender for Cloud?", o: ["Resume la postura de seguridad según las recomendaciones, y sube conforme se resuelven", "El costo mensual de los servicios de seguridad", "El porcentaje de disponibilidad comprometido en el SLA", "Cuántos usuarios de la organización tienen MFA activado"], a: [0], e: "Defender for Cloud revisa la configuración de los recursos y emite recomendaciones; el secure score las resume en una calificación que mejora conforme se atienden. Cubre recursos de Azure, de AWS, de GCP y on-premises, y el nivel básico de CSPM, incluido el secure score, no tiene costo.", c: "Recomendaciones resueltas, score que sube." },
  { id: "nube9", tp: "nube", q: "Además de máquinas virtuales, storage, bases de datos y redes, ¿qué otros servicios entran en la definición de cloud computing de Microsoft?", o: ["Internet de las cosas (IoT), machine learning e inteligencia artificial", "Solo infraestructura tradicional: cómputo, disco y red", "Únicamente correo electrónico y herramientas de oficina", "Nada más: la nube es hardware rentado y ya"], a: [0], e: "Microsoft define cloud computing como la entrega de servicios de cómputo por internet, e incluye tanto la infraestructura clásica (VMs, storage, bases de datos, redes) como servicios que un datacenter propio no suele ofrecer: IoT, machine learning e inteligencia artificial.", c: "IoT, machine learning e IA también entran en la definición." },
  { id: "benef14", tp: "benef", q: "Un equipo configura autoescalado, despliegue desde plantillas y alertas automáticas por métricas. ¿A qué tipo de manageability corresponde?", o: ["Gestión de la nube: cómo se administran los recursos", "Gestión en la nube: con qué herramientas se trabaja", "Gobernanza, porque define políticas", "Alta disponibilidad, porque evita caídas"], a: [0], e: "La gestión de la nube (management of the cloud) es lo que los recursos hacen por sí mismos: escalar según la demanda, desplegarse desde plantillas, monitorear su salud y reemplazar lo que falla, y avisar por alertas. La gestión en la nube (management in the cloud) son los medios para trabajar: portal web, línea de comandos, APIs y PowerShell.", c: "De la nube: lo que los recursos hacen solos. En la nube: la herramienta con la que entras." },
  { id: "tipos9", tp: "tipos", q: "En IaaS, ¿de qué se hace cargo el proveedor de nube?", o: ["Del hardware, la conectividad a internet y la seguridad física; lo demás es del cliente", "Del sistema operativo y de sus parches", "De la aplicación completa, incluidos los datos", "De la configuración de red y de la base de datos"], a: [0], e: "IaaS es la categoría más flexible y la que más control da, a cambio de más responsabilidad. El proveedor mantiene hardware, red hacia internet y seguridad física; el cliente se encarga de instalar y parchar el sistema operativo, configurar la red y administrar bases de datos y storage. Sus escenarios típicos son lift and shift y los entornos de pruebas y desarrollo.", c: "IaaS: rentas el hardware, el resto lo operas tú." },
  { id: "costo13", tp: "costo", q: "¿Qué entrega la pricing calculator de Azure?", o: ["Una estimación de costo a partir del consumo que capturas, antes de desplegar nada", "La factura real del mes en curso", "Un descuento automático sobre los recursos desplegados", "El desglose de lo ya gastado por resource group"], a: [0], e: "La pricing calculator convierte el uso previsto en un costo estimado: eliges productos, capturas cuánto esperas consumir y arma la estimación, que puedes guardar, exportar a Excel y compartir por enlace. Con sesión iniciada muestra los precios negociados del acuerdo. Lo que ya se gastó se ve en Cost Management.", c: "Calculator: antes de gastar. Cost Management: lo que ya se gastó." },
  { id: "admin12", tp: "admin", q: "¿Qué es el portal de Azure?", o: ["Una consola web unificada que corre en el navegador para crear y administrar todos los recursos", "Una aplicación de escritorio que se instala en Windows", "Un intérprete de línea de comandos", "Un lenguaje de plantillas para describir infraestructura"], a: [0], e: "El portal es una interfaz gráfica que corre en cualquier navegador soportado, sin instalar nada. Está presente en todos los datacenters de Azure, lo que lo hace resistente a la caída de uno solo, y se actualiza sin ventanas de mantenimiento. Sus dashboards se personalizan y se pueden compartir con otras personas de la organización.", c: "Portal: gráfico y en el navegador. CLI y PowerShell: línea de comandos." },
  { id: "monitor12", tp: "monitor", q: "¿Cuáles son las cinco categorías de recomendaciones de Azure Advisor?", o: ["Confiabilidad, seguridad, rendimiento, costo y excelencia operativa", "Costo, seguridad, respaldo, licenciamiento y soporte", "Disponibilidad, latencia, cumplimiento, costo y capacidad", "Seguridad, redes, identidad, storage y cómputo"], a: [0], e: "Advisor analiza la configuración de los recursos y su telemetría de uso, y devuelve recomendaciones personalizadas en cinco categorías: reliability, security, performance, cost y operational excellence. Sus recomendaciones de seguridad vienen de Microsoft Defender for Cloud.", c: "Cinco categorías, y el costo es una de ellas." },
  { id: "monitor13", tp: "monitor", q: "Quieres recibir aviso cuando Azure programe mantenimiento que afecte los servicios y regiones que tu organización usa. ¿Qué configuras?", o: ["Alertas de Service Health", "La página pública de Azure status", "Resource health de cada recurso", "Una recomendación de Azure Advisor"], a: [0], e: "Service Health da una vista personalizada de los servicios y regiones que usa la organización, con avisos de interrupciones, mantenimiento planeado y avisos de salud, y permite configurar alertas para enterarte por el canal que prefieras. Azure status es la página pública con la vista global de todos los servicios, y Resource health mira un recurso individual.", c: "Personalizado y con alertas: Service Health. Página pública global: Azure status." },
];
